// Apply every patch registered for `id` to a freshly loaded mini-bundle instance.
// Mutates instance.shaders[program] in place (the `glsl` string by default, or the
// `field` stage — e.g. `vertex` for multi-stage programs like deposit) before
// registerEffect runs.
export function applyUpstreamShaderPatches (id, instance) {
  for (const patch of PATCHES) {
    if (patch.id !== id) continue
    const shader = instance.shaders && instance.shaders[patch.program]
    if (!shader) {
      throw new Error(`upstream shader patch ${id}/${patch.program}: program missing from the loaded mini-bundle`)
    }
    const target = shader[patch.field || 'glsl']
    if (typeof target !== 'string') {
      throw new Error(`upstream shader patch ${id}/${patch.program}${patch.field ? `/${patch.field}` : ''}: does not carry GLSL text on the loaded mini-bundle`)
    }
    if (target === patch.to) continue // already carries the upstream GLSL
    if (target !== patch.from) {
      throw new Error(`upstream shader patch ${id}/${patch.program}${patch.field ? `/${patch.field}` : ''}: vendored GLSL matches neither the pinned revision nor the patched target — refresh this file against vendor/fetch.sh's engine`)
    }
    shader[patch.field || 'glsl'] = patch.to
  }
}
